\n// 复原坐标里的层位；向下取 0.5 m，与 model.layerAt:
// layer index in rest coordinates; offset down 0.5 m, matching model.layerAt floor(e/40 + 1e-9) (a surface exactly on a boundary takes the layer below)
float s = vRest.z - uA * cos(6.2831853 * vRest.x / {$0}) - 0.5;
int ii = int(clamp(floor(s / {$1}), 0.0, {$2}));
if (uFlip > 0.5 && vRest.y > {$3}) ii = (ii + 1) - 7 * ((ii + 1) / 7);
vec3 col = uCol[0]; int pat = uPat[0];
for (int k = 0; k < 7; k++) { if (k == ii) { col = uCol[k]; pat = uPat[k]; } }
float topF = step(0.6, abs(vObjN.y));
float u = vRest.x, w = s, ink = 0.0;
if (pat == 1) { vec2 q = vec2(u / 9.0, w / 7.0); vec2 f = fract(q + vec2(0.5 * floor(q.y), 0.0)); ink = step(abs(f.x - 0.5 - (f.y - 0.5) * 0.6), 0.07) * step(abs(f.y - 0.5), 0.28); }
if (pat == 2) { vec2 f = abs(fract(vec2(u / 10.0, w / 8.0)) - 0.5); ink = step(0.44, max(f.x, f.y)); }
if (pat == 3) { vec2 q = vec2(u / 8.0, w / 7.0); vec2 f = fract(q + vec2(0.5 * floor(q.y), 0.0)) - 0.5; ink = step(length(f), 0.16); }
col = mix(col, col * 0.45, ink * 0.75 * (1.0 - topF));
float fr = s / {$4}; float dl = abs(fr - floor(fr + 0.5)) * {$5};
float lw = fwidth(s) * 1.2 + 0.25;
float onLine = (s > 20.0 && s < {$6} + uGhost * 40.0) ? 1.0 - smoothstep(lw * 0.5, lw, dl) : 0.0;
float alpha = opacity;
if (uGhost > 0.5) {
  float L = onLine * step(0.45, fract(u / 14.0)) * (1.0 - topF);
  col = mix(mix(uTint, col, 0.35), uLine, L);
  alpha = mix(0.12 * uGhostK, 0.8, L);
} else {
  col = mix(col, uLine, onLine * 0.85);
  float nearF = max(vEdge.z * (1.0 - step(14.0, vEdge.x)), vEdge.w * (1.0 - step(14.0, vEdge.y)));
  col = mix(col, uBrec * (0.75 + 0.5 * hash2(floor(vRest.xy / 3.0))), uBrecOn * topF * nearF * 0.9);
  col *= 0.97 + 0.06 * hash2(floor(vRest.xz / 4.0) + floor(vRest.y / 4.0) * 0.37);   // fine rock grain (±3 %, does not affect layer color recognition)
  // step 2 axis picked: keep that column at original color and brighten slightly, darken the rest (brightening alone cannot reach 15 % on light layers)
  float hi = 1.0 - smoothstep(uHiW - 2.0, uHiW, abs(u - uHiX));
  col *= mix(1.0, mix(0.5, 1.08, hi), uHi);
  float ew = fwidth(u) * 1.5 + 0.3;
  col = mix(col, vec3(1.0), uHi * 0.9 * (1.0 - smoothstep(ew * 0.5, ew, abs(abs(u - uHiX) - uHiW))));
}
vec4 diffuseColor = vec4(col, alpha);
